  Nu = `Aletapahtuma odottaa Valven hyväksyntää`,
  Pu = `Käytä oikealla näkyvää painiketta lähettääksesi kauppasivun tarkistettavaksi. Tämä on tehtävä vähintään seitsemän päivää ennen toivottua julkaisupäivää, jotta sivun tarkistamiseen ja mahdollisten muutosten tekemiseen olisi riittävästi aikaa.`,
  Fu = `Steamin tiimi ottaa sinuun yhteyttä Steamworksin tukipyynnön avulla, jos sivulle täytyy tehdä muutoksia. Näet tukipyynnön ja voit tarvittaessa lisätä kommentteja klikkaamalla oikealla olevaa painiketta.`,
  Iu = `Kun sivu on merkitty hyväksytyksi, kumppani voi julkaista alen ja tehdä siitä julkisen.`,
  Lu = `Pyydä tarkistusta`,
  Ru = `Pyydä tarkistusta`,
  zu = `Luo tukipyynnön kauppasivun tarkistamiseksi ennen sen julkaisemista. Tee pyyntö, kun kauppasivun lopullinen kuvitus ja pelisisältö ovat valmiina.`,
  Bu = `Tämä luo Steamworks-tukipyynnön, jossa pyydät Valvea tarkistamaan kauppasivusi. Lähetä pyyntö vasta sen jälkeen, kun kaikki kauppasivun esittelykuvat, tekstit ja pelit ovat valmiita julkaistaviksi.`,
  Vu = `Varmista, että tapahtuman otsikko ja tarkoitus on kuvattu selvästi sivun yläreunassa. Esittelyjä varten saatat tarvita tekstiosion sivun yläreunaan kuvailemaan esittelyä ja sen toimintaa.`,
  Hu = `Tarkistuksen jälkeen alesivu lukitaan. Jos haluat tehdä muutoksia tarkistuksen tai tapahtuman alkamisen jälkeen, ilmoita kommenttikentässä, mitä muutokset sisältävät ja miksi niitä ei voitu tehdä ennen tarkistusta.`,
  Uu = `Valinnainen: anna lisätietoja kauppasivun tarkistajille.`,
  Wu = `Valitse kumppanit, jotka pääsevät myös näkemään tukipyynnön`,
  Gu = `Valinnainen: Jos valitset tämän, muut kumppanitilin jäsenet näkevät tukipyynnön ja voivat vastata siihen. Oletuksena ainoastaan tukipyynnön luonut käyttäjä voi nähdä ja päivittää sen tai lähettää vastauksen.`,
  Ku = `Tukipyynnön lähettäminen epäonnistui. Yritä myöhemmin uudelleen.`,
  qu = `Tukipyynnön luonti epäonnistui, sillä kyseisen tyyppinen tukipyyntö on jo lähetetty. Suorita toisen kauppasivusi tarkistus ennen kuin lähetät tukipyynnön tai päivitä olemassa oleva tukipyyntö sisältämään tämän kauppasivun tarkistus.`,
