  WB = `Esikatsele dynaaminen näyttö`,
  GB = `Alla olevaan osioon on otettu käyttöön dynaaminen näyttö. Voit esikatsella toiminnon aloittamalla testin. Näkymä nollautuu, kun poistut välilehdeltä.`,
  KB = `Aloita testitila`,
