  sV = `Nimeä nyt. Äänestä joulukuussa.`,
  cV = `Steam-palkinnot ovat päättyneet tämän tapahtuman osalta. Tsekkaa syys- ja talvialen aikaan täältä vuosittaiset Steam-palkinnot!`,
