  EH = `Paras peli tien päällä`,
  DH = `Olivatko pelin mekaniikat mukaansatempaavia? Tekikö tarina vaikutuksen? Olivatko hahmojen ja ulkoasun suunnittelu omaa luokkaansa? Jäitkö koukkuun moninpeliin? Olipa syy mikä tahansa, tämän vuoden paras peli on klassikko jo syntyessään.`,
  OH = `Vuoden paras VR-peli ei tyydy jäljittelemään todellisuutta, vaan parantaa sitä huomattavasti. VR-laseista otetaan kaikki irti ja virtuaalista rimaa nostetaan entisestään.`,
