  NH = `Peli ei sovi arkajaloille, vaan vaatii sitkeyttä. Rankka mutta rakas peli.`,
  PH = `Tämä peli ansaitsee tunnustuksen erinomaisesta musiikistaan. Sen alkuperäinen ääniraita on rautaa! `,
  FH = `Joinain päivinä vain tuhti tarinapohjainen peli maistuu, ja tämä peli antaa makeaa mahan täydeltä. Yhtä mukaansatempaava kuin saippuaooppera ja yhtä taidokkaasti punottu kuin maineikkaan TV-sarjan käsikirjoitus. Hatunnosto teille, pelintekijät. Herätitte meissä tunteita!`,
  IH = `Tämä peli on vastalääke kiireiselle päivälle. Se on rauhallinen, rentouttava ja vie huolet mennessään. Päivän zen-hetki.`,
  LH = `Peli oli niin hyvä, että halusit ottaa sen mukaan joka paikkaan. Ja niin teitkin! Peli vei mukanaan jo kotonakin, mutta tien päällä sitä oli vielä mahtavampi pelata.`,
  RH = `Vain VR`,
  zH = `VR-tuettu`,
