  gU = `Osa 3/4`,
  _U = `Osa 4/4`,
  vU = `Jadekeisari kutsui kaikki valtakuntansa olennot kisaamaan siitä, kuka ehtisi ensin taivaalliselle palatsille. Kaksitoista ensimmäistä pääsisi keisarin uuteen kalenteriin.

Nokkela rotta ylitti joen taivaalliseen valtakuntaan ensimmäisenä. Se ei piitannut uimisesta, vaan salamatkusti vahvan ja vakaan härän selässä. Rotta loikkasi innoissaan keisarin puutarhaan juuri ennen kuin parivaljakko rantautui. 

Hillitty härkä ylitti joen huolettomana. Kisa ei sitä kiinnostanut, vaan se iloitsi rotan voitosta.`,
  yU = `Oman tiensä kulkijana tiikeri taittoi matkaa liian hitaasti päihittääkseen härän. Tiikeristä kolmas sija oli parempi kuin ei mitään. 

Vikkelä jänis loikkasi ajelehtivan tukin kyytiin. Jäniksellä oli onni matkassa, sillä suotuisa tuuli puhalsi venhoseen vauhtia. 

Lentävä lohikäärme huomasi yläilmoista pulassa olevan kylän ja syöksyi tietenkin hätiin. Lohikäärmeen aiheuttama tuulenpuuska antoi jänikselle tuulta purjeisiin. Lohikäärmeelle kunnia oli tärkeämpää kuin voitto. Se oli varsin tyytyväinen viidenteen sijaan.`,
  bU = `Salamyhkäinen käärme piti matkaa aivan liian pitkänä, joten se kietoitui huomaamatta hevosen etukavion ympärille.

Kun hevonen laukkasi kohti maalilinjaa, käärme sujahti piilostaan, pelästytti ratsun ja kiemurteli kuudenneksi. Säikky hevonen köpötteli perässä.`,
  xU = `Vuohi, apina ja kukko matkasivat kimpassa, mutta vuohi sai juhtana suosiolla napata kahdeksannen sijan. Iloinen apina loikki yhdeksänneksi ja kukko tepasteli arvokkaana kymmenenneksi, tyytyväisenä reilusta kisasta.

Koira halusi vain leikkiä ja polskia ja tyytyi mieluusti 11. sijaan. Häntäpäässä perille pääsi sika, joka oli pysähtynyt matkalla hiukopalalle ja torkuille. Se tiesi viisaudessaan, että jokainen eläin on vuorollaan keisarin suosiossa.`,
